+NS_IMETHODIMP VirtualFolderWrapperFactory::CreateInstance(const nsIID& iid,
+                                                          void** result) {
+  RefPtr inst = new VirtualFolderWrapper();
+  return inst->QueryInterface(iid, result);
+}
